/**
 * Conservative final pass over generated Janino source. It only performs transformations whose legality can be proven
 * from local generated-source structure. Unrecognised source is returned byte-for-byte unchanged.
 */
final class LmdbNativeGeneratedSourceOptimizer {

	private static final String MARKER = "/* rdf4j-fused-sip-factorized */";
	private static final Pattern CLASS_DECL = Pattern.compile(".*\\bclass\\s+([A-Za-z_$][\\w$]*).*\\{\\s*$");
	private static final Pattern ARRAY_DOMAIN = Pattern.compile(
			"^(\\s*)long\\[\\]\\s+([A-Za-z_$][\\w$]*)\\s*=\\s*(.+(?:materializeNativeDomain|borrowNativeDomain|nativeDomain).+);\\s*$");
	private static final Pattern CHILD_VALUE = Pattern.compile(
			"^(\\s*)long\\s+([A-Za-z_$][\\w$]*)\\s*=\\s*([A-Za-z_$][\\w$]*)\\.(?:neighborAt|neighborAtInt)\\(([^;]+)\\);\\s*$");
	private static final Pattern FILTER_CONTINUE = Pattern.compile(
			"^(\\s*)if\\s*\\((.+(?:test|accept|compare|filter).+)\\)\\s*\\{?\\s*(continue(?:\\s+[A-Za-z_$][\\w$]*)?;)\\s*}\\s*$");
	private static final Pattern IDENTIFIER = Pattern.compile("\\b[A-Za-z_$][\\w$]*\\b");
	private static final Pattern BIND_OPEN = Pattern
			.compile("^\\s*public\\s+void\\s+bind\\s*\\(KernelContext\\s+context\\)\\s*\\{\\s*$");
	private static final Pattern CLOSE_OPEN = Pattern.compile("^\\s*public\\s+void\\s+close\\s*\\(\\)\\s*\\{\\s*$");

	private LmdbNativeGeneratedSourceOptimizer() {
	}

	static String optimize(String source) {
		return optimize(source, true);
	}

	static String optimize(String source, boolean telemetry) {
		if (source == null || source.indexOf(MARKER) >= 0 || source.indexOf("class ") < 0) {
			return source;
		}
		String lineSeparator = source.indexOf("\r\n") >= 0 ? "\r\n" : "\n";
		String[] input = source.split("\\R", -1);

		// First establish a collision-free, binding-local domain ordinal and the consumers whose variable name proves
		// the relationship. A child with no matching domain is left untouched; an ALL-domain guard is not called SIP.
		LinkedHashMap<String, DomainInfo> domains = new LinkedHashMap<>();
		Map<String, Set<String>> consumers = new HashMap<>();
		for (String line : input) {
			Matcher domain = ARRAY_DOMAIN.matcher(line);
			if (domain.matches()) {
				String key = normalize(domain.group(2));
				domains.computeIfAbsent(key,
						ignored -> new DomainInfo(domains.size(), domain.group(2), domain.group(3)));
			}
		}
		for (String line : input) {
			Matcher child = CHILD_VALUE.matcher(line);
			if (child.matches()) {
				String key = normalize(child.group(2));
				if (domains.containsKey(key)) {
					consumers.computeIfAbsent(key, ignored -> new HashSet<>()).add(child.group(3) + ".neighborRun");
				}
			}
		}

		List<String> lines = new ArrayList<>(input.length + 32);
		lines.add(MARKER);
		for (String line : input) {
			Matcher domain = ARRAY_DOMAIN.matcher(line);
			if (domain.matches()) {
				lines.add(line);
				if (!telemetry) {
					continue;
				}
				String key = normalize(domain.group(2));
				DomainInfo info = domains.get(key);
				String indent = domain.group(1);
				lines.add(indent + "org.eclipse.rdf4j.sail.lmdb.evaluation.LmdbFusedKernelRuntime.installExactDomain("
						+ info.id + ", \"" + escape(info.variable) + "\", \"generated:" + escape(info.producer)
						+ "\", " + info.variable + ", 0, " + info.variable + ".length);");
				for (String consumer : consumers.getOrDefault(key, Set.of())) {
					lines.add(indent
							+ "org.eclipse.rdf4j.sail.lmdb.evaluation.LmdbFusedKernelRuntime.registerDomainConsumer("
							+ info.id + ", \"" + escape(consumer) + "\");");
				}
				continue;
			}
			Matcher child = CHILD_VALUE.matcher(line);
			if (child.matches()) {
				String key = normalize(child.group(2));
				DomainInfo info = domains.get(key);
				lines.add(line);
				if (telemetry && info != null) {
					lines.add(child.group(1)
							+ "if (!org.eclipse.rdf4j.sail.lmdb.evaluation.LmdbFusedKernelRuntime.sipMayContain("
							+ info.id + ", " + child.group(2) + ")) { continue; }");
				}
				continue;
			}
			lines.add(line);
		}

		List<FilterMove> filterMoves = relocateStraightLineFilters(lines, telemetry);
		injectClassStateAndLifecycle(lines, filterMoves, telemetry);
		return String.join(lineSeparator, lines);
	}

	private static void injectClassStateAndLifecycle(List<String> lines, List<FilterMove> moves, boolean telemetry) {
		if (!telemetry) {
			return;
		}
		int classLine = -1;
		for (int i = 0; i < lines.size(); i++) {
			if (CLASS_DECL.matcher(lines.get(i)).matches()) {
				classLine = i;
				break;
			}
		}
		if (classLine >= 0 && !moves.isEmpty()) {
			int insert = classLine + 1;
			for (FilterMove move : moves) {
				lines.add(insert++, "    private long rdf4jRfTest" + move.id + ";");
				lines.add(insert++, "    private long rdf4jRfReject" + move.id + ";");
			}
		}

		for (int i = 0; i < lines.size(); i++) {
			if (BIND_OPEN.matcher(lines.get(i)).matches()) {
				int insert = i + 1;
				if (!containsNearby(lines, insert, "markNestedKernelFactorization")) {
					lines.add(insert++,
							"        org.eclipse.rdf4j.sail.lmdb.evaluation.LmdbFusedKernelRuntime.markNestedKernelFactorization();");
				}
				for (FilterMove move : moves) {
					lines.add(insert++,
							"        org.eclipse.rdf4j.sail.lmdb.evaluation.LmdbFusedKernelRuntime.recordGeneratedFilterPlacement("
									+ move.key + ", \"" + escape(move.label) + "\", " + move.originalStage + ", "
									+ move.selectedStage + ");");
				}
				break;
			}
		}
		if (!moves.isEmpty()) {
			for (int i = 0; i < lines.size(); i++) {
				if (CLOSE_OPEN.matcher(lines.get(i)).matches()) {
					int insert = i + 1;
					for (FilterMove move : moves) {
						lines.add(insert++,
								"        org.eclipse.rdf4j.sail.lmdb.evaluation.LmdbFusedKernelRuntime.observeGeneratedFilter("
										+ move.key + ", \"" + escape(move.label) + "\", " + move.originalStage + ", "
										+ move.selectedStage + ", rdf4jRfTest" + move.id + ", rdf4jRfTest" + move.id
										+ " - rdf4jRfReject" + move.id + ", 0L, rdf4jRfReject" + move.id + ");");
					}
					break;
				}
			}
		}
	}

	private static boolean containsNearby(List<String> lines, int from, String text) {
		for (int i = from; i < Math.min(lines.size(), from + 6); i++) {
			if (lines.get(i).contains(text)) {
				return true;
			}
		}
		return false;
	}

	/**
	 * Relocates only within one straight-line brace depth and instruments the resulting guard with primitive counters.
	 */
	private static List<FilterMove> relocateStraightLineFilters(List<String> lines, boolean telemetry) {
		ArrayList<FilterMove> moves = new ArrayList<>();
		for (int at = 0; at < lines.size(); at++) {
			Matcher filter = FILTER_CONTINUE.matcher(lines.get(at));
			if (!filter.matches()) {
				continue;
			}
			String expression = filter.group(2);
			if (expression.contains("optional") || expression.contains("minus") || expression.contains("leftJoin")
					|| expression.contains("random") || expression.contains("now(")) {
				continue;
			}
			Set<String> required = identifiers(expression);
			int earliest = at;
			int depth = depthBefore(lines, at);
			for (int candidate = at - 1; candidate >= 0; candidate--) {
				String line = lines.get(candidate);
				if (depthBefore(lines, candidate) != depth || isSemanticBarrier(line)) {
					break;
				}
				if (definesAny(line, required)) {
					earliest = candidate + 1;
					break;
				}
				earliest = candidate;
			}
			int id = moves.size();
			String label = abbreviate(expression, 160);
			int key = stableHash(label + '@' + at);
			FilterMove move = new FilterMove(id, key, label, at, earliest);
			String indent = filter.group(1);
			String instrumented = telemetry
					? indent + "rdf4jRfTest" + id + "++;\n" + indent + "if (" + expression
							+ ") { rdf4jRfReject" + id + "++; " + filter.group(3) + " }"
					: indent + "if (" + expression + ") { " + filter.group(3) + " }";
			lines.remove(at);
			lines.add(earliest, instrumented);
			moves.add(move);
			// Continue after the relocated line. The pass is idempotent because the class marker prevents a second run.
			at = Math.max(at, earliest);
		}
		return moves;
	}

	private static boolean isSemanticBarrier(String line) {
		return line.contains("OPTIONAL") || line.contains("MINUS") || line.contains("LeftJoin")
				|| line.contains("try {") || line.contains("catch (") || line.contains("finally")
				|| line.contains("emit") || line.contains("addResult") || line.contains("return ");
	}

	private static Set<String> identifiers(String expression) {
		Set<String> result = new HashSet<>();
		Matcher matcher = IDENTIFIER.matcher(expression);
		while (matcher.find()) {
			String value = matcher.group();
			if (!isKeyword(value)) {
				result.add(value);
			}
		}
		return result;
	}

	private static boolean isKeyword(String value) {
		return switch (value) {
		case "if", "true", "false", "null", "long", "int", "boolean", "double", "continue", "this" -> true;
		default -> Character.isUpperCase(value.charAt(0));
		};
	}

	private static boolean definesAny(String line, Set<String> required) {
		for (String value : required) {
			if (line.matches(".*\\b(?:long|int|boolean|double|Object|var)\\s+" + Pattern.quote(value) + "\\b.*")) {
				return true;
			}
		}
		return false;
	}

	private static int depthBefore(List<String> lines, int end) {
		int depth = 0;
		for (int i = 0; i < end; i++) {
			String line = lines.get(i);
			for (int c = 0; c < line.length(); c++) {
				char ch = line.charAt(c);
				if (ch == '{') {
					depth++;
				} else if (ch == '}') {
					depth--;
				}
			}
		}
		return depth;
	}

	private static String normalize(String name) {
		int start = 0;
		while (start < name.length() && (name.charAt(start) == '_' || name.charAt(start) == 'v')) {
			start++;
		}
		int end = name.length();
		for (String suffix : new String[] { "Domain", "Values", "Keys", "Ids", "Array" }) {
			if (end - start > suffix.length() && name.regionMatches(true, end - suffix.length(), suffix, 0,
					suffix.length())) {
				end -= suffix.length();
				break;
			}
		}
		if (end - start > 1 && name.charAt(end - 1) == 's') {
			end--;
		}
		return name.substring(start, end);
	}

	private static int stableHash(String value) {
		int hash = 0x811c9dc5;
		for (int i = 0; i < value.length(); i++) {
			hash ^= value.charAt(i);
			hash *= 0x01000193;
		}
		return hash;
	}

	private static String abbreviate(String value, int limit) {
		return value.length() <= limit ? value : value.substring(0, limit - 3) + "...";
	}

	private static String escape(String value) {
		return value.replace("\\", "\\\\").replace("\"", "\\\"").replace("\n", "\\n").replace("\r", "\\r");
	}

	private record DomainInfo(int id, String variable, String producer) {
	}

	private record FilterMove(int id, int key, String label, int originalStage, int selectedStage) {
	}
}
